```python
import numpy as np

class Model:
    def __init__(self):
        self.weights = None

    def fit(self, X, y):
        raise NotImplementedError("Subclasses must implement this method")

    def predict(self, X):
        raise NotImplementedError("Subclasses must implement this method")

class LinearModel(Model):
    def fit(self, X, y):
        # Simple linear regression using least squares
        self.weights = np.linalg.inv(X.T @ X) @ X.T @ y

    def predict(self, X):
        return X @ self.weights

class RandomModel(Model):
    def fit(self, X, y):
        pass

    def predict(self, X):
        return np.random.rand(len(X))

class GaussianProcessModel(Model):
    def fit(self, X, y):
        # Placeholder for Gaussian Process implementation
        pass

    def predict(self, X):
        return np.random.normal(size=len(X))

class ContextualMultiArmedBandit:
    def __init__(self, models):
        self.models = models
        self.rewards = {model: [] for model in models}

    def select_arm(self, context):
        predictions = [model.predict([context])[0] for model in self.models]
        selected_model_index = np.argmax(predictions)
        return selected_model_index

    def update(self, arm, reward):
        self.rewards[self.models[arm]].append(reward)

# Example usage
if __name__ == "__main__":
    # Create instances of the models
    linear_model = LinearModel()
    random_model = RandomModel()
    gaussian_process_model = GaussianProcessModel()

    # Initialize the bandit with the models
    bandit = ContextualMultiArmedBandit([linear_model, random_model, gaussian_process_model])

    # Simulate some contexts and rewards
    contexts = np.array([[1, 2], [3, 4], [5, 6]])
    true_rewards = np.array([0.8, 0.9, 0.7])  # True rewards for each context

    for context, true_reward in zip(contexts, true_rewards):
        # Select an arm based on the current context
        selected_arm = bandit.select_arm(context)

        # Assume we get a noisy observation of the true reward
        observed_reward = true_reward + np.random.normal(0, 0.1)

        # Update the bandit with the observed reward
        bandit.update(selected_arm, observed_reward)

    print("Rewards per model:", bandit.rewards)
```

### Explanation:

1. **Model Class**: This is an abstract base class for all models. It defines methods `fit` and `predict`, which need to be implemented by subclasses.
2. **LinearModel Class**: Implements a simple linear regression model.
3. **RandomModel Class**: Generates random predictions.
4. **GaussianProcessModel Class**: A placeholder for a more complex model like Gaussian Processes.
5. **ContextualMultiArmedBandit Class**: Manages multiple models and selects actions based on their predictions. It also updates the internal state after receiving rewards.
6. **Example Usage**: Demonstrates how to use these classes together in a simulation scenario where contexts and rewards are provided.

This code provides a basic framework for implementing a contextual multi-armed bandit problem with multiple models. You can extend it further by adding more sophisticated models or improving the selection strategy.

