        require(_exists(id), "CredsToken: Credential type already exists");
        _setURI(string(abi.encodePacked("https://example.com/api/", toString(id), ".json")));
        _credentialNames[id] = name;
        emit CredentialTypeAdded(id);
    }

    /**
     * @dev Returns the name of a credential type.
     */
    function getCredentialName(uint256 id) public view returns (string memory) {
        return _credentialNames[id];
    }

    /**
     * @dev Mints a specified amount of a credential type to an address.
     * Only the owner can call this function.
     */
    function mint(address account, uint256 id, uint256 amount, bytes memory data) external onlyOwner {
        _mint(account, id, amount, data);
    }

    /**
     * @dev Burns a specified amount of a credential type from an address.
     */
    function burn(address account, uint256 id, uint256 amount) external {
        require(balanceOf(account, id) >= amount, "CredsToken: Insufficient balance");
        _burn(account, id, amount);
    }

    /**
     * @dev Transfers a specified amount of a credential type from one address to another.
     */
    function safeTransferFrom(
        address from,
        address to,
        uint256 id,
        uint256 amount,
        bytes memory data
    ) public override {
        super.safeTransferFrom(from, to, id, amount, data);
    }

    /**
     * @dev Helper function to convert uint256 to string.
     */
    function toString(uint256 value) internal pure returns (string memory) {
        if (value == 0) {
            return "0";
        }
        uint256 temp = value;
        uint256 digits;
        while (temp != 0) {
            digits++;
            temp /= 10;
        }
        bytes memory buffer = new bytes(digits);
        while (value != 0) {
            digits -= 1;
            buffer[digits] = bytes1(uint8(48 + uint256(value % 10)));
            value /= 10;
        }
        return string(buffer);
    }
}
