Here is an example of a Metal compute kernel for Gaussian blurring an image:

```metal
#include <metal_stdlib>
using namespace metal;

kernel void gaussian_blur(
    texture2d<float, access::read> input [[texture(0)]],
    texture2d<float, access::write> output [[texture(1)]],
    uint2 gid [[thread_position_in_grid]]
) {
    float4 color = float4(0);

    // Define the Gaussian weights
    const float weights[5] = { 0.227027, 0.394966, 0.227027, 0.079381, 0.016216 };

    // Calculate the sum of the weights
    float weight_sum = 0;
    for (int i = 0; i < 5; ++i) {
        weight_sum += weights[i];
    }

    // Apply the Gaussian filter
    for (int y = -2; y <= 2; ++y) {
        for (int x = -2; x <= 2; ++x) {
            int sample_x = clamp(gid.x + x, 0, input.get_width() - 1);
            int sample_y = clamp(gid.y + y, 0, input.get_height() - 1);

            float4 sample_color = input.read(int2(sample_x, sample_y));
            color += sample_color * weights[y + 2];
        }
    }

    // Normalize the result by dividing by the sum of the weights
    color /= weight_sum;

    // Write the blurred pixel to the output texture
    output.write(color, gid);
}
```

