```javascript
function findEntityKey(jsonData, targetKey) {
    const results = [];

    // Helper function to perform recursive search
    function search(obj, path = '') {
        if (typeof obj === 'object' && obj !== null) {
            Object.entries(obj).forEach(([key, value]) => {
                const newPath = path ? `${path}.${key}` : key;
                if (key === targetKey) {
                    results.push({ value: value, path: newPath });
                }
                search(value, newPath);
            });
        }
    }

    // Start searching from the root of the provided JSON data
    search(jsonData);

    return results;
}

// Example usage:
const jsonData = {
    "name": "John",
    "age": 30,
    "address": {
        "street": "123 Main St",
        "city": "Anytown",
        "state": "CA"
    },
    "contacts": [
        { "type": "email", "value": "john@example.com" },
        { "type": "phone", "value": "+1-555-1234" }
    ]
};

const targetKey = 'value';
const result = findEntityKey(jsonData, targetKey);
console.log(result); // Output: [{ value: 'john@example.com', path: 'contacts[0].value' }, { value: '+1-555-1234', path: 'contacts[1].value' }]
```

This function uses recursion to traverse nested objects and arrays within the JSON structure. When it finds a match for the `targetKey`, it records both the value and its path in the resulting array. This approach ensures that even deeply nested entities can be located efficiently.

