```

Here's the complete Rust code:

```rust
use std::fs;
use std::process::Command;
use reqwest;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Read URLs from a file
    let url_file_path = "urls.txt";
    let content = fs::read_to_string(url_file_path)?;
    let urls: Vec<&str> = content.lines().collect();

    // Separate YouTube URLs from other URLs
    let mut youtube_urls = Vec::new();
    let mut other_urls = Vec::new();

    for url in &urls {
        if is_youtube_url(url) {
            youtube_urls.push(url);
        } else {
            other_urls.push(url);
        }
    }

    println!("YouTube URLs:");
    for url in &youtube_urls {
        println!("{}", url);
    }

    println!("\nOther URLs:");
    for url in &other_urls {
        println!("{}", url);
    }

    // Download YouTube URLs using yt-dlp
    for url in youtube_urls {
        Command::new("yt-dlp")
            .arg(url)
            .output()?;
    }

    Ok(())
}

fn is_youtube_url(url: &str) -> bool {
    url.starts_with("https://www.youtube.com/") || url.starts_with("https://youtu.be/")
}
```

### Explanation:

1. **Reading URLs from a File**:
   - The program reads all lines from a file named `urls.txt`.

2. **Separating YouTube URLs**:
   - It checks each URL to see if it starts with either `"https://www.youtube.com/"` or `"https://youtu.be/"`.
   - If it does, the URL is considered a YouTube URL and added to the `youtube_urls` vector; otherwise, it goes into the `other_urls` vector.

3. **Downloading YouTube URLs**:
   - Using the `Command` struct from the standard library, the program runs the `yt-dlp` command for each YouTube URL found.

4. **Output**:
   - Prints out both sets of URLs before attempting to download them.

